use kni_core::capture_fit::{clean_emitted_ring,round_and_clean_ring};
use kni_core::cff_container::{charstring,CffGlyph};
use kni_core::reference_slice::{DrawnGlyph,Point,ReferenceRing,Span};
fn p(x:f64,y:f64)->Point{Point{x,y}}
fn encoded(r:ReferenceRing)->Vec<u8>{charstring(&CffGlyph{name:"synthetic".into(),advance:100,outline:DrawnGlyph{glyph_id:"synthetic".into(),rings:vec![r]}}).unwrap()}
fn zero_spans(r:&ReferenceRing)->usize{let mut current=r.start;let mut count=0;for s in &r.spans{let(end,zero)=match s{Span::Line{end}=>(*end,*end==current),Span::Cubic{control_one,control_two,end}=>(*end,*end==current&&*control_one==current&&*control_two==current)};count+=usize::from(zero);current=end;}count}
#[test]fn exact_post_fit_cleanup_preserves_clean_integer_charstring_bytes(){let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(10.,0.)},Span::Line{end:p(10.,10.)},Span::Line{end:p(0.,0.)}]};let before=encoded(r.clone());let after=clean_emitted_ring(r.clone(),0.);assert_eq!(zero_spans(&after),0);assert_eq!(before,encoded(after));assert_eq!(before,encoded(round_and_clean_ring(&r,1.)));}
#[test]fn rounding_collapsed_spans_removed_without_dropping_loop_or_retracted_handles(){let r=ReferenceRing{start:p(0.1,0.1),spans:vec![Span::Line{end:p(10.1,0.1)},Span::Line{end:p(10.2,0.2)},Span::Cubic{control_one:p(10.2,0.2),control_two:p(10.3,0.3),end:p(10.4,0.4)},Span::Cubic{control_one:p(10.,0.),control_two:p(15.,5.),end:p(10.,0.)},Span::Line{end:p(0.1,0.1)}]};let clean=round_and_clean_ring(&r,1.);assert_eq!(clean.spans.len(),3);assert_eq!(zero_spans(&clean),0);match &clean.spans[1]{Span::Cubic{control_one,control_two,end}=>{assert_eq!(*control_one,p(10.,0.));assert_eq!(*control_two,p(15.,5.));assert_eq!(*end,p(10.,0.));},_=>panic!("looping cubic must survive")};let expected=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(10.,0.)},Span::Cubic{control_one:p(10.,0.),control_two:p(15.,5.),end:p(10.,0.)},Span::Line{end:p(0.,0.)}]};assert_eq!(encoded(clean),encoded(expected));}
#[test]fn nonadjacent_repeated_oncurve_is_not_silently_removed(){let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(10.,0.)},Span::Line{end:p(10.,10.)},Span::Line{end:p(10.,0.)},Span::Line{end:p(0.,0.)}]};assert_eq!(encoded(r.clone()),encoded(clean_emitted_ring(r,0.)));}
#[test]fn fully_collapsed_ring_policy_is_explicit(){let r=ReferenceRing{start:p(0.,0.),spans:vec![Span::Line{end:p(0.,0.)}]};let after=clean_emitted_ring(r.clone(),0.);assert_eq!(zero_spans(&after),1);assert_eq!(encoded(r),encoded(after));}
